import React from 'react';
import { DropDown } from '../../components/DropDown';
import ChatComponent from '../../components/ChatBubble';
import { ChatTextInput } from '../../components/ChatTextInput';
import { ChatVoiceInput } from '../../components/ChatVoiceInput';
import SuggestedPrompts from '@/app/components/SuggestedPrompts';
//font
import {DM_Sans} from "next/font/google";

const DMsansFont = DM_Sans({
  subsets: ["latin"],
})

const MindTalk = () => {
   return (
    // Main container uses flexbox to structure the layout
    <div className="flex h-screen bg-white font-sans">
      
      {/* The NavBar would be a sibling to the main content area. 
        It would be uncommented in your actual app.
      */}
      {/* <NavBar /> */}

      {/* Main content area takes up the remaining space */}
      <main className="flex-1 flex flex-col h-screen w-full overflow-hidden">
        
        {/* Header: Stays at the top, doesn't scroll */}
        <header className="flex-shrink-0 bg-white/80 backdrop-blur-sm z-10 border-b border-gray-200">
            <div className="navbar bg-transparent max-w-5xl mx-auto px-4 md:px-5">
                 <div className="navbar-start">
                    <button className="p-2 -ml-2 rounded-md hover:bg-gray-100 text-gray-600">
                         <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="3" x2="21" y1="12" y2="12"/><line x1="3" x2="21" y1="6" y2="6"/><line x1="3" x2="21" y1="18" y2="18"/></svg>
                    </button>
                 </div>
                 <div className="navbar-center">
                    <h1 className="text-3xl md:text-5xl text-[#CE2746] font-bold">Heart Line</h1>
                 </div>
                 <div className="navbar-end">
                    <DropDown />
                 </div>
            </div>
        </header>

        {/* Chat & Prompts Area: This section grows and scrolls */}
        <div className="flex-1 flex flex-col items-center overflow-y-auto">
          {/* This inner div pushes the chat bubble to the bottom initially */}
          <div className="w-full max-w-5xl mx-auto flex-1 flex flex-col justify-end px-4">
             <div className="py-8">
                <ChatBubble />
                {/* Future chat messages would be added here */}
             </div>
          </div>
          
          {/* Suggested prompts appear below the chat area */}
          <div className="w-full">
            <SuggestedPrompts />
          </div>
        </div>

        {/* Footer: Stays at the bottom, doesn't scroll */}
        <footer className="flex-shrink-0 bg-white pt-3 pb-4 border-t border-gray-200">
          <div className="max-w-4xl mx-auto px-4">
            <div className="flex w-full items-center gap-2 md:gap-4">
              <div className="flex-1">
                <ChatTextInput />
              </div>
              <ChatVoiceInput />
            </div>
          </div>
        </footer>
      </main>
    </div>
  );
    
}

export default MindTalk
